package app.badcat.client

import android.content.Context
import android.graphics.BitmapFactory
import android.util.Base64
import android.widget.ImageView

/** Tintable copies of the three retained original bottom-navigation icons. */
internal object BadcatNavigationIcons {
    private const val SEARCH = ""
    private const val FAVORITES = ""
    private const val MINE = ""

    fun create(context: Context, key: String, tint: Int): ImageView {
        val encoded = when (key) {
            "search" -> SEARCH
            "favorites" -> FAVORITES
            "mine" -> MINE
            else -> SEARCH
        }
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        return ImageView(context).apply {
            setImageBitmap(BitmapFactory.decodeByteArray(bytes, 0, bytes.size))
            setColorFilter(tint)
            scaleType = ImageView.ScaleType.FIT_CENTER
            contentDescription = key
        }
    }
}
